 if(['years','rate'].includes(e.target.id))scenario();
 if(e.target.id==='placeSearch'){const q=e.target.value.trim().toLowerCase();const found=scopePlaces().filter(p=>(p.name+' '+p.county).toLowerCase().includes(q));$('#placeResults').innerHTML=q?found.slice(0,18).map(p=>`<button type="button" data-place="${p.id}">${esc(p.name)} <small>· ${esc(p.county)} County</small></button>`).join('')||'<p>No matching covered place.</p>':'';$('#placeResults').hidden=!q;$('#placeSearch').setAttribute('aria-expanded',String(Boolean(q)));}
 if(e.target.id==='resourceSearch'){const q=e.target.value.toLowerCase();$('#resourceResults').innerHTML=resourceGroups(place.resources.filter(r=>(r.title+' '+r.category).toLowerCase().includes(q)));}
 if(e.target.id==='directorySearch'){const q=e.target.value.toLowerCase();clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(!q){$('#view').innerHTML=coverage();$('#directorySearch').focus();return;}const matches=eligible().filter(p=>(p.name+' '+p.county).toLowerCase().includes(q));$('#directoryResults').innerHTML=matches.slice(0,48).map(placeCard).join('')||empty('No matching locality','Try another name or district.');if(matches.length>48)$('#directoryResults').insertAdjacentHTML('beforeend','<p class="note">Showing 48 of '+matches.length+' matches. Refine your search to see the rest.</p>');$('#view .pagination').hidden=true;},120);}
