 readHash();initProfile();
 try{catalog=await api('/api/cal/catalog');policies=(await api('/cal/data/policies.json')).policies;const p=byId(state.place);if(!p)state.place='p0669070';await render();const params=new URLSearchParams(location.search);if(state.view==='future'){if(params.has('years'))$('#years').value=Math.max(1,Math.min(10,Number(params.get('years'))||5));if(params.has('rate'))$('#rate').value=Math.max(25,Math.min(175,Number(params.get('rate'))||100));scenario();}}
